import time

class RateLimiter:
    """
    A Rate Limiter implemented using a timestamp dictionary with a sliding window approach.
    This method uses a hash map to maintain counts of requests received at each second, 
    allowing efficient tracking and management of request limits within the defined time window.
    """

    def __init__(self, max_requests: int, window_seconds: float):
        self.max_requests = max_requests
        self.window_seconds = window_seconds
        self.requests = {}

    def allow(self) -> bool:
        current_time = int(time.time())
        # Remove outdated timestamps
        for t in list(self.requests.keys()):
            if t < current_time - self.window_seconds:
                del self.requests[t]

        # Count current requests in the window
        current_count = sum(self.requests.values())

        if current_count < self.max_requests:
            if current_time in self.requests:
                self.requests[current_time] += 1
            else:
                self.requests[current_time] = 1
            return True
        return False
